#ifndef SOUTHPAW_CLASSIFIER_H
#define SOUTHPAW_CLASSIFIER_H

#include <stdint.h>
#include "features.h"

enum PunchType : uint8_t {
  PUNCH_UNKNOWN = 0,   // the model gave a letter this firmware doesn't know (shouldn't happen)
  PUNCH_JAB,
  PUNCH_CROSS,
  PUNCH_HOOK,
  PUNCH_UPPERCUT,
  PUNCH_NONE,          // not a punch (other hand punching, bouncing, feints): nothing is sent
};

// Runs this hand's decision tree (classifier_model.c, generated by train_classifier.py --export).
PunchType classify(const PunchFeatures& f);

// Protocol letter: J, C, H, U. PUNCH_NONE gives 'N' and PUNCH_UNKNOWN 'X', for the USB
// debug lines only: neither is in the protocol, so neither is sent over BLE.
char punch_code(PunchType t);
const char* punch_name(PunchType t);

#endif
